window.ARCHON_EXTRACTOR_SCRIPT_CODE = "/**\n * EXTRACTOR MAESTRO UNIFICADO DE ARCHON.GG (CON DOMPARSER)\n * 40 SPECS + ÁRBOL DE TALENTOS (HTML/SVG 1:1) + HERO TREES + BIS GEAR + ABALORIOS HEALERS\n * \n * INSTRUCCIONES:\n * 1. Ve a https://www.archon.gg/wow\n * 2. Abre la consola (F12 -> Console).\n * 3. Pega este código y presiona Enter.\n * 4. Descargará automáticamente 'archon_data.js'.\n */\n\n(async function extractAllArchonData() {\n  console.log('%c🚀 INICIANDO EXTRACCIÓN UNIFICADA DE ARCHON.GG (40 SPECS)...', 'color: #38bdf8; font-weight: bold; font-size: 14px;');\n\n  const SPECS = [\n    { classKey: 'deathknight', specKey: 'blood', classSlug: 'death-knight', specSlug: 'blood' },\n    { classKey: 'deathknight', specKey: 'frost', classSlug: 'death-knight', specSlug: 'frost' },\n    { classKey: 'deathknight', specKey: 'unholy', classSlug: 'death-knight', specSlug: 'unholy' },\n    { classKey: 'demonhunter', specKey: 'havoc', classSlug: 'demon-hunter', specSlug: 'havoc' },\n    { classKey: 'demonhunter', specKey: 'vengeance', classSlug: 'demon-hunter', specSlug: 'vengeance' },\n    { classKey: 'demonhunter', specKey: 'devourer', classSlug: 'demon-hunter', specSlug: 'devourer' },\n    { classKey: 'druid', specKey: 'balance', classSlug: 'druid', specSlug: 'balance' },\n    { classKey: 'druid', specKey: 'feral', classSlug: 'druid', specSlug: 'feral' },\n    { classKey: 'druid', specKey: 'guardian', classSlug: 'druid', specSlug: 'guardian' },\n    { classKey: 'druid', specKey: 'restoration', classSlug: 'druid', specSlug: 'restoration' },\n    { classKey: 'evoker', specKey: 'devastation', classSlug: 'evoker', specSlug: 'devastation' },\n    { classKey: 'evoker', specKey: 'preservation', classSlug: 'evoker', specSlug: 'preservation' },\n    { classKey: 'evoker', specKey: 'augmentation', classSlug: 'evoker', specSlug: 'augmentation' },\n    { classKey: 'hunter', specKey: 'beastmastery', classSlug: 'hunter', specSlug: 'beast-mastery' },\n    { classKey: 'hunter', specKey: 'marksmanship', classSlug: 'hunter', specSlug: 'marksmanship' },\n    { classKey: 'hunter', specKey: 'survival', classSlug: 'hunter', specSlug: 'survival' },\n    { classKey: 'mage', specKey: 'arcane', classSlug: 'mage', specSlug: 'arcane' },\n    { classKey: 'mage', specKey: 'fire', classSlug: 'mage', specSlug: 'fire' },\n    { classKey: 'mage', specKey: 'frost', classSlug: 'mage', specSlug: 'frost' },\n    { classKey: 'monk', specKey: 'brewmaster', classSlug: 'monk', specSlug: 'brewmaster' },\n    { classKey: 'monk', specKey: 'mistweaver', classSlug: 'monk', specSlug: 'mistweaver' },\n    { classKey: 'monk', specKey: 'windwalker', classSlug: 'monk', specSlug: 'windwalker' },\n    { classKey: 'paladin', specKey: 'holy', classSlug: 'paladin', specSlug: 'holy' },\n    { classKey: 'paladin', specKey: 'protection', classSlug: 'paladin', specSlug: 'protection' },\n    { classKey: 'paladin', specKey: 'retribution', classSlug: 'paladin', specSlug: 'retribution' },\n    { classKey: 'priest', specKey: 'discipline', classSlug: 'priest', specSlug: 'discipline' },\n    { classKey: 'priest', specKey: 'holy', classSlug: 'priest', specSlug: 'holy' },\n    { classKey: 'priest', specKey: 'shadow', classSlug: 'priest', specSlug: 'shadow' },\n    { classKey: 'rogue', specKey: 'assassination', classSlug: 'rogue', specSlug: 'assassination' },\n    { classKey: 'rogue', specKey: 'outlaw', classSlug: 'rogue', specSlug: 'outlaw' },\n    { classKey: 'rogue', specKey: 'subtlety', classSlug: 'rogue', specSlug: 'subtlety' },\n    { classKey: 'shaman', specKey: 'elemental', classSlug: 'shaman', specSlug: 'elemental' },\n    { classKey: 'shaman', specKey: 'enhancement', classSlug: 'shaman', specSlug: 'enhancement' },\n    { classKey: 'shaman', specKey: 'restoration', classSlug: 'shaman', specSlug: 'restoration' },\n    { classKey: 'warlock', specKey: 'affliction', classSlug: 'warlock', specSlug: 'affliction' },\n    { classKey: 'warlock', specKey: 'demonology', classSlug: 'warlock', specSlug: 'demonology' },\n    { classKey: 'warlock', specKey: 'destruction', classSlug: 'warlock', specSlug: 'destruction' },\n    { classKey: 'warrior', specKey: 'arms', classSlug: 'warrior', specSlug: 'arms' },\n    { classKey: 'warrior', specKey: 'fury', classSlug: 'warrior', specSlug: 'fury' },\n    { classKey: 'warrior', specKey: 'protection', classSlug: 'warrior', specSlug: 'protection' }\n  ];\n\n  const HEALER_TARGETS = [\n    { classKey: 'paladin', specKey: 'holy', urlPath: 'holy/paladin' },\n    { classKey: 'priest', specKey: 'discipline', urlPath: 'discipline/priest' },\n    { classKey: 'priest', specKey: 'holy', urlPath: 'holy/priest' },\n    { classKey: 'shaman', specKey: 'restoration', urlPath: 'restoration/shaman' },\n    { classKey: 'druid', specKey: 'restoration', urlPath: 'restoration/druid' },\n    { classKey: 'monk', specKey: 'mistweaver', urlPath: 'mistweaver/monk' },\n    { classKey: 'evoker', specKey: 'preservation', urlPath: 'preservation/evoker' }\n  ];\n\n  const presetsResults = {};\n  const healerTrinketsResults = {};\n  const parser = new DOMParser();\n\n  console.log('%c--- PASO 1/2: Escaneando 40 Specs (Stats, Árboles, Talentos, BiS) ---', 'color: #f59e0b; font-weight: bold;');\n  let currentIdx = 0;\n\n  for (const item of SPECS) {\n    currentIdx++;\n    if (!presetsResults[item.classKey]) presetsResults[item.classKey] = {};\n    presetsResults[item.classKey][item.specKey] = {\n      raid: { m: 0, c: 0, h: 0, v: 0, dps: '', dpsLabel: 'DPS', popularity: '', topLogUrl: '', talents: '', heroTree: '', talentTreeHtml: '', bisGear: [] },\n      mplus: { m: 0, c: 0, h: 0, v: 0, dps: '', dpsLabel: 'DPS', popularity: '', topLogUrl: '', talents: '', heroTree: '', talentTreeHtml: '', bisGear: [] }\n    };\n\n    console.log('[' + currentIdx + '/' + SPECS.length + '] 🔍 ' + item.classKey + ' (' + item.specKey + ')...');\n\n    for (const mode of ['raid', 'mythic-plus']) {\n      const modeKey = mode === 'raid' ? 'raid' : 'mplus';\n      const url = mode === 'raid'\n        ? 'https://www.archon.gg/wow/builds/' + item.specSlug + '/' + item.classSlug + '/raid/overview/mythic/all-bosses'\n        : 'https://www.archon.gg/wow/builds/' + item.specSlug + '/' + item.classSlug + '/mythic-plus/overview/high-keys/all-dungeons/this-week';\n\n      try {\n        const res = await fetch(url);\n        if (!res.ok) {\n          console.warn('   ⚠️ ' + modeKey.toUpperCase() + ' HTTP ' + res.status + ' en ' + url);\n          continue;\n        }\n        const htmlText = await res.text();\n        const doc = parser.parseFromString(htmlText, 'text/html');\n\n        // 1. Stats\n        let m = 0, c = 0, h = 0, v = 0;\n        doc.querySelectorAll('.builds-stat-priority-section__container').forEach(container => {\n          const labelEl = container.querySelector('.builds-stat-priority-section__container__stat-box__label');\n          const valEl = container.querySelector('.builds-stat-priority-section__container__stat-box__value');\n          if (labelEl && valEl) {\n            const label = labelEl.textContent.trim().toLowerCase();\n            const val = parseInt(valEl.textContent.replace(/,/g, ''), 10);\n            if (label.includes('mast') || label.includes('maestr')) m = val;\n            else if (label.includes('crit')) c = val;\n            else if (label.includes('hast') || label.includes('celer')) h = val;\n            else if (label.includes('vers')) v = val;\n          }\n        });\n        presetsResults[item.classKey][item.specKey][modeKey].m = m;\n        presetsResults[item.classKey][item.specKey][modeKey].c = c;\n        presetsResults[item.classKey][item.specKey][modeKey].h = h;\n        presetsResults[item.classKey][item.specKey][modeKey].v = v;\n\n        // 2. Talents String\n        const talentLink = doc.querySelector('a[href*=\"wowhead.com/talent-calc/blizzard/\"]');\n        if (talentLink) {\n          const tMatch = talentLink.href.match(/blizzard\\/([^\"/?#]+)/i);\n          if (tMatch) presetsResults[item.classKey][item.specKey][modeKey].talents = tMatch[1].trim();\n        }\n\n        // 3. Hero Tree Title\n        const heroEl = doc.querySelector('.talent-tree__hero-title');\n        if (heroEl) {\n          presetsResults[item.classKey][item.specKey][modeKey].heroTree = heroEl.textContent.trim();\n        }\n\n        // 3.1 Métricas de Rendimiento (DPS / HPS) y Enlace a Top Log (Warcraft Logs)\n        const logLink = doc.querySelector('a[href*=\"warcraftlogs.com/reports/\"]');\n        if (logLink) {\n          presetsResults[item.classKey][item.specKey][modeKey].topLogUrl = logLink.getAttribute('href') || logLink.href || '';\n          const boxEl = logLink.closest('div')?.parentElement;\n          if (boxEl) {\n            const boxText = boxEl.textContent || '';\n            const dpsMatch = boxText.match(/(?:DPS|HPS)\\s*([\\d.]+[kKmM]?)/i);\n            if (dpsMatch) presetsResults[item.classKey][item.specKey][modeKey].dps = dpsMatch[1];\n          }\n        }\n\n        // 4. Árbol de Talentos 1:1 (HTML + SVG) limpio\n        const treeSection = doc.querySelector('.builds-talent-tree-build-section__talent-trees') || doc.querySelector('.talent-tree--container');\n        if (treeSection) {\n          // A. Eliminar tablas de alternativas secundarias\n          treeSection.querySelectorAll('.builds-talent-tree-build-section__talent-tree-alternatives, [class*=\"talent-tree-alternatives\"]').forEach(el => el.remove());\n\n          // B. Corregir insignias de clase y spec para evitar sprites distorsionados\n          const classBadge = treeSection.querySelector('.talent-tree__container--class .talent-tree__description__icon');\n          if (classBadge) {\n            classBadge.innerHTML = '<img src=\"https://wow.zamimg.com/images/wow/icons/large/classicon_' + item.classKey + '.jpg\" alt=\"' + item.classKey + '\" style=\"width:2.5rem;height:2.5rem;border-radius:9999px;border:2px solid #f59e0b;object-fit:cover;display:block;\" onerror=\"this.src=\\'https://wow.zamimg.com/images/wow/icons/large/inv_misc_questionmark.jpg\\'\"/>';\n          }\n\n          let treeHtml = treeSection.outerHTML;\n          treeHtml = treeHtml.replace(/<i class=\"zmdi zmdi-copy\"><\\/i>/g, '<i class=\"fa-solid fa-copy ml-1.5 text-amber-400\"></i>');\n          treeHtml = treeHtml.replace(/<i class=\"zmdi zmdi-edit\"><\\/i>/g, '<i class=\"fa-solid fa-arrow-up-right-from-square ml-1.5 text-amber-400\"></i>');\n          presetsResults[item.classKey][item.specKey][modeKey].talentTreeHtml = treeHtml;\n        }\n\n        // 5. BiS Gear\n        const bisGear = [];\n        const gearElements = doc.querySelectorAll('[class*=\"gear-section__gear-item\"], [class*=\"gear-item\"]');\n        \n        gearElements.forEach(el => {\n          const itemLink = el.querySelector('a[href*=\"wowhead.com/item=\"]');\n          if (!itemLink) return;\n\n          const rawHref = itemLink.getAttribute('href') || itemLink.href || '';\n          const idMatch = rawHref.match(/item=(\\d+)/);\n          if (!idMatch) return;\n          const itemId = parseInt(idMatch[1], 10);\n\n          // Capturar rel (bonus, pcs, gems) o query params del href\n          let itemParams = itemLink.getAttribute('rel') || '';\n          if (!itemParams && rawHref.includes('?')) {\n            itemParams = rawHref.substring(rawHref.indexOf('?') + 1);\n          }\n          itemParams = itemParams.replace(/&amp;/g, '&').replace(/^\\?/, '').trim();\n\n          const nameSpan = el.querySelector('a.epic span, a[href*=\"wowhead.com/item=\"] span') || itemLink;\n          let itemName = nameSpan ? nameSpan.textContent.replace(/\\u00a0/g, ' ').trim() : ('Item ' + itemId);\n\n          const popEl = el.querySelector('[class*=\"popularity\"]');\n          let popularity = 0;\n          if (popEl) {\n            const pMatch = popEl.textContent.match(/([\\d.]+)%/);\n            if (pMatch) popularity = parseFloat(pMatch[1]);\n          }\n\n          const parsesEl = el.querySelector('[class*=\"parses\"]');\n          let parses = 0;\n          if (parsesEl) {\n            const paMatch = parsesEl.textContent.replace(/,/g, '').match(/(\\d+)/);\n            if (paMatch) parses = parseInt(paMatch[1], 10);\n          }\n\n          if (!bisGear.some(x => x.id === itemId)) {\n            bisGear.push({ id: itemId, name: itemName, params: itemParams, popularity, parses });\n          }\n        });\n\n        presetsResults[item.classKey][item.specKey][modeKey].bisGear = bisGear;\n        const hasTree = !!presetsResults[item.classKey][item.specKey][modeKey].talentTreeHtml;\n        console.log('   ✅ ' + modeKey.toUpperCase() + ' OK -> BiS Items: ' + bisGear.length + ' | Árbol 1:1: ' + (hasTree ? 'SÍ' : 'NO'));\n      } catch (err) {\n        console.warn('   ⚠️ Fallo en ' + item.specKey + ' (' + modeKey + '):', err.message);\n      }\n    }\n    await new Promise(r => setTimeout(r, 200));\n  }\n\n  // 2. EXTRACCIÓN DETALLADA DE ABALORIOS HEALER\n  console.log('%c--- PASO 2/2: Escaneando Tablas de Abalorios para Healers ---', 'color: #f59e0b; font-weight: bold;');\n  const HEALER_MODES = [\n    { key: 'mplus', urlSub: 'mythic-plus/trinkets/high-keys/all-dungeons/this-week' },\n    { key: 'raid', urlSub: 'raid/trinkets/mythic/all-bosses' }\n  ];\n\n  function parseHtmlTrinkets(doc) {\n    const rows = [];\n    doc.querySelectorAll('table.react-table tbody tr').forEach(tr => {\n      const link = tr.querySelector('a[href*=\"wowhead.com/item=\"]');\n      if (!link) return;\n      const itemMatch = link.href.match(/item=(\\d+)/);\n      if (!itemMatch) return;\n      const itemId = parseInt(itemMatch[1], 10);\n      const nameEl = tr.querySelector('.icon__label, a[href*=\"wowhead.com/item=\"] span span');\n      const name = nameEl ? nameEl.textContent.trim() : ('Item ' + itemId);\n      const popEl = tr.querySelector('.react-table__cell--popularityAndReportLink span, .react-table__cell--popularity span');\n      const popText = popEl ? popEl.textContent.trim() : '0%';\n      const popMatch = popText.match(/([0-9.]+)%/);\n      const popularity = popMatch ? parseFloat(popMatch[1]) : 0;\n      const maxKeyEl = tr.querySelector('.react-table__cell--maxKey span');\n      const maxKey = maxKeyEl ? maxKeyEl.textContent.trim() : '';\n      const imgEl = tr.querySelector('img.icon__image');\n      let icon = '';\n      if (imgEl && imgEl.src) {\n        const im = imgEl.src.match(/\\/abilities\\/([^.]+)/);\n        if (im) icon = im[1];\n      }\n      rows.push({ itemId, name, popularity, maxKey, icon });\n    });\n    return rows;\n  }\n\n  for (const h of HEALER_TARGETS) {\n    if (!healerTrinketsResults[h.classKey]) healerTrinketsResults[h.classKey] = {};\n    if (!healerTrinketsResults[h.classKey][h.specKey]) healerTrinketsResults[h.classKey][h.specKey] = {};\n\n    for (const m of HEALER_MODES) {\n      const url = 'https://www.archon.gg/wow/builds/' + h.urlPath + '/' + m.urlSub;\n      console.log('🩺 Descargando abalorios (' + h.classKey + ' - ' + h.specKey + ' - ' + m.key + ')...');\n      try {\n        const resp = await fetch(url);\n        if (resp.ok) {\n          const html = await resp.text();\n          const doc = parser.parseFromString(html, 'text/html');\n          const trinkets = parseHtmlTrinkets(doc);\n          healerTrinketsResults[h.classKey][h.specKey][m.key] = trinkets;\n        } else {\n          healerTrinketsResults[h.classKey][h.specKey][m.key] = [];\n        }\n      } catch (e) {\n        healerTrinketsResults[h.classKey][h.specKey][m.key] = [];\n      }\n      await new Promise(r => setTimeout(r, 200));\n    }\n  }\n\n  // 3. GENERACIÓN DEL ARCHIVO FINAL UNIFICADO\n  const fileContent = '// Archon.gg Datos Oficiales Unificados (Stats + Árboles Talentos 1:1 + BiS Gear + Abalorios Healers)\\n' +\n    'window.ARCHON_LAST_UPDATED = ' + JSON.stringify(new Date().toISOString()) + ';\\n' +\n    'window.ARCHON_PRESETS = ' + JSON.stringify(presetsResults, null, 2) + ';\\n\\n' +\n    'window.ARCHON_HEALER_TRINKETS = ' + JSON.stringify(healerTrinketsResults, null, 2) + ';\\n';\n\n  const blob = new Blob([fileContent], { type: 'text/javascript' });\n  const downloadUrl = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = downloadUrl;\n  a.download = 'archon_data.js';\n  document.body.appendChild(a);\n  a.click();\n  document.body.removeChild(a);\n  URL.revokeObjectURL(downloadUrl);\n\n  console.log('%c🎉 ¡EXTRACCIÓN UNIFICADA FINALIZADA CON ÉXITO (40 SPECS CON ÁRBOLES 1:1)! Archivo archon_data.js descargado.', 'color: #22c55e; font-weight: bold; font-size: 16px;');\n  return { ARCHON_PRESETS: presetsResults, ARCHON_HEALER_TRINKETS: healerTrinketsResults };\n})();";
window.WOWHEAD_EXTRACTOR_SCRIPT_CODE = "(async function extractWowheadBis() {\n  console.log(\"%c🚀 Iniciando Extracción Oficial con ICONOS EXACTOS DE TOOLTIPS (40 Specs)...\", \"color: #f59e0b; font-size: 15px; font-weight: bold;\");\n\n  const SPECS = [\n    // Paladín\n    { classKey: 'paladin', specKey: 'retribution', urlSlug: 'paladin/retribution/enchants-gems-pve-dps' },\n    { classKey: 'paladin', specKey: 'holy_paladin', urlSlug: 'paladin/holy/enchants-gems-pve-healer' },\n    { classKey: 'paladin', specKey: 'protection_paladin', urlSlug: 'paladin/protection/enchants-gems-pve-tank' },\n    // Guerrero\n    { classKey: 'warrior', specKey: 'arms', urlSlug: 'warrior/arms/enchants-gems-pve-dps' },\n    { classKey: 'warrior', specKey: 'fury', urlSlug: 'warrior/fury/enchants-gems-pve-dps' },\n    { classKey: 'warrior', specKey: 'protection_warrior', urlSlug: 'warrior/protection/enchants-gems-pve-tank' },\n    // DK\n    { classKey: 'deathknight', specKey: 'blood', urlSlug: 'death-knight/blood/enchants-gems-pve-tank' },\n    { classKey: 'deathknight', specKey: 'frost_dk', urlSlug: 'death-knight/frost/enchants-gems-pve-dps' },\n    { classKey: 'deathknight', specKey: 'unholy', urlSlug: 'death-knight/unholy/enchants-gems-pve-dps' },\n    // Cazador\n    { classKey: 'hunter', specKey: 'beastmastery', urlSlug: 'hunter/beast-mastery/enchants-gems-pve-dps' },\n    { classKey: 'hunter', specKey: 'marksmanship', urlSlug: 'hunter/marksmanship/enchants-gems-pve-dps' },\n    { classKey: 'hunter', specKey: 'survival', urlSlug: 'hunter/survival/enchants-gems-pve-dps' },\n    // Chamán\n    { classKey: 'shaman', specKey: 'elemental', urlSlug: 'shaman/elemental/enchants-gems-pve-dps' },\n    { classKey: 'shaman', specKey: 'enhancement', urlSlug: 'shaman/enhancement/enchants-gems-pve-dps' },\n    { classKey: 'shaman', specKey: 'restoration_shaman', urlSlug: 'shaman/restoration/enchants-gems-pve-healer' },\n    // Pícaro\n    { classKey: 'rogue', specKey: 'assassination', urlSlug: 'rogue/assassination/enchants-gems-pve-dps' },\n    { classKey: 'rogue', specKey: 'outlaw', urlSlug: 'rogue/outlaw/enchants-gems-pve-dps' },\n    { classKey: 'rogue', specKey: 'subtlety', urlSlug: 'rogue/subtlety/enchants-gems-pve-dps' },\n    // Monje\n    { classKey: 'monk', specKey: 'brewmaster', urlSlug: 'monk/brewmaster/enchants-gems-pve-tank' },\n    { classKey: 'monk', specKey: 'windwalker', urlSlug: 'monk/windwalker/enchants-gems-pve-dps' },\n    { classKey: 'monk', specKey: 'mistweaver', urlSlug: 'monk/mistweaver/enchants-gems-pve-healer' },\n    // DH\n    { classKey: 'demonhunter', specKey: 'havoc', urlSlug: 'demon-hunter/havoc/enchants-gems-pve-dps' },\n    { classKey: 'demonhunter', specKey: 'vengeance', urlSlug: 'demon-hunter/vengeance/enchants-gems-pve-tank' },\n    { classKey: 'demonhunter', specKey: 'devourer', urlSlug: 'demon-hunter/devourer/enchants-gems-pve-dps' },\n    // Druida\n    { classKey: 'druid', specKey: 'balance', urlSlug: 'druid/balance/enchants-gems-pve-dps' },\n    { classKey: 'druid', specKey: 'feral', urlSlug: 'druid/feral/enchants-gems-pve-dps' },\n    { classKey: 'druid', specKey: 'guardian', urlSlug: 'druid/guardian/enchants-gems-pve-tank' },\n    { classKey: 'druid', specKey: 'restoration_druid', urlSlug: 'druid/restoration/enchants-gems-pve-healer' },\n    // Mago\n    { classKey: 'mage', specKey: 'arcane', urlSlug: 'mage/arcane/enchants-gems-pve-dps' },\n    { classKey: 'mage', specKey: 'fire', urlSlug: 'mage/fire/enchants-gems-pve-dps' },\n    { classKey: 'mage', specKey: 'frost_mage', urlSlug: 'mage/frost/enchants-gems-pve-dps' },\n    // Brujo\n    { classKey: 'warlock', specKey: 'affliction', urlSlug: 'warlock/affliction/enchants-gems-pve-dps' },\n    { classKey: 'warlock', specKey: 'demonology', urlSlug: 'warlock/demonology/enchants-gems-pve-dps' },\n    { classKey: 'warlock', specKey: 'destruction', urlSlug: 'warlock/destruction/enchants-gems-pve-dps' },\n    // Sacerdote\n    { classKey: 'priest', specKey: 'discipline', urlSlug: 'priest/discipline/enchants-gems-pve-healer' },\n    { classKey: 'priest', specKey: 'holy_priest', urlSlug: 'priest/holy/enchants-gems-pve-healer' },\n    { classKey: 'priest', specKey: 'shadow', urlSlug: 'priest/shadow/enchants-gems-pve-dps' },\n    // Evocador\n    { classKey: 'evoker', specKey: 'devastation', urlSlug: 'evoker/devastation/enchants-gems-pve-dps' },\n    { classKey: 'evoker', specKey: 'preservation', urlSlug: 'evoker/preservation/enchants-gems-pve-healer' },\n    { classKey: 'evoker', specKey: 'augmentation', urlSlug: 'evoker/augmentation/enchants-gems-pve-dps' }\n  ];\n\n  const iconCache = {};\n  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));\n\n  async function fetchRealIcon(id, type) {\n    if (!id) return 'inv_misc_questionmark';\n    if (iconCache[id]) return iconCache[id];\n    try {\n      const endpoint = type === 'spell' \n        ? `https://nether.wowhead.com/tooltip/spell/${id}`\n        : `https://nether.wowhead.com/tooltip/item/${id}`;\n      const res = await fetch(endpoint);\n      if (res.ok) {\n        const data = await res.json();\n        if (data && data.icon) {\n          iconCache[id] = data.icon;\n          return data.icon;\n        }\n      }\n    } catch (e) {}\n    return 'inv_misc_questionmark';\n  }\n\n  function parseTablesFromHtml(html) {\n    const normalizedHtml = html.replace(/<tr>\\s*([^<]+)<\\/td>/gi, '<tr><td>$1</td>');\n    const parser = new DOMParser();\n    const doc = parser.parseFromString(normalizedHtml, \"text/html\");\n    let tables = Array.from(doc.querySelectorAll(\"table\"));\n\n    if (tables.length === 0) {\n      doc.querySelectorAll(\"noscript\").forEach(ns => {\n        const subDoc = parser.parseFromString(ns.textContent || ns.innerHTML || \"\", \"text/html\");\n        tables.push(...subDoc.querySelectorAll(\"table\"));\n      });\n    }\n\n    const rawItems = [];\n\n    tables.forEach((table) => {\n      const heading = table.previousElementSibling?.innerText || table.closest(\"section\")?.querySelector(\"h2, h3\")?.innerText || \"\";\n      const rows = table.querySelectorAll(\"tr\");\n\n      rows.forEach((row) => {\n        const cols = row.querySelectorAll(\"td\");\n        if (cols.length < 2) return;\n\n        const label = cols[0].innerText.trim();\n        const links = Array.from(cols[1].querySelectorAll(\"a[href*='/item='], a[href*='/spell=']\"));\n        if (links.length === 0) {\n          const fallbackLink = cols[1].querySelector(\"a\");\n          if (fallbackLink) links.push(fallbackLink);\n        }\n        if (links.length === 0) return;\n\n        links.forEach(link => {\n          const name = link.innerText.trim();\n          if (!name) return;\n          const href = link.getAttribute(\"href\") || \"\";\n          const matchItem = href.match(/item=(\\d+)/);\n          const matchSpell = href.match(/spell=(\\d+)/);\n          const id = matchItem ? parseInt(matchItem[1]) : (matchSpell ? parseInt(matchSpell[1]) : 0);\n          const entityType = matchSpell ? 'spell' : 'item';\n\n          const isConsumable = /flask|potion|food|rune|oil|weapon buff|feast/i.test(label) || /consumable/i.test(heading);\n          const isEnchant = /weapon|chest|cloak|back|wrist|bracer|boots|feet|legs|ring|finger|helm|head|shoulder|hand|main hand|off hand/i.test(label) || /enchant/i.test(heading) || /^enchant\\s/i.test(name);\n\n          if (isConsumable) {\n            rawItems.push({ category: 'consumable', type: label, id, entityType, name, desc: name });\n          } else if (isEnchant) {\n            const slotName = /main hand|off hand/i.test(label) ? `Weapon (${label})` : label;\n            rawItems.push({ category: 'enchant', slot: slotName, id, entityType, name, desc: name });\n          }\n        });\n      });\n    });\n\n    // Fallback para frascos de Evoker Preservación\n    if (!rawItems.some(i => i.category === 'consumable' && /flask/i.test(i.type))) {\n      const flaskLinks = Array.from(doc.querySelectorAll(\"a[href*='flask-']\"));\n      flaskLinks.forEach(link => {\n        const name = link.innerText.trim();\n        const matchId = (link.getAttribute(\"href\") || \"\").match(/item=(\\d+)/);\n        if (name && matchId) {\n          const id = parseInt(matchId[1]);\n          if (!rawItems.some(i => i.id === id)) {\n            rawItems.unshift({ category: 'consumable', type: 'Flask', id, entityType: 'item', name, desc: name });\n          }\n        }\n      });\n    }\n\n    return rawItems;\n  }\n\n  const results = {};\n\n  for (let i = 0; i < SPECS.length; i++) {\n    const s = SPECS[i];\n    if (!results[s.classKey]) results[s.classKey] = {};\n\n    const url = `https://www.wowhead.com/guide/classes/${s.urlSlug}`;\n    try {\n      const res = await fetch(url);\n      if (res.ok) {\n        const html = await res.text();\n        const rawItems = parseTablesFromHtml(html);\n        \n        const enchants = [];\n        const consumables = [];\n\n        for (const item of rawItems) {\n          const icon = await fetchRealIcon(item.id, item.entityType);\n          if (item.category === 'enchant') {\n            enchants.push({ slot: item.slot, id: item.id, name: item.name, icon, desc: item.desc });\n          } else {\n            consumables.push({ type: item.type, id: item.id, name: item.name, icon, desc: item.desc });\n          }\n        }\n\n        results[s.classKey][s.specKey] = { enchants, consumables };\n        console.log(`[${i + 1}/${SPECS.length}] ✓ ${s.classKey} - ${s.specKey}: ${enchants.length} encantamientos y ${consumables.length} consumibles (iconos oficiales obtenidos).`);\n      }\n    } catch (e) {\n      console.error(`Error en ${url}:`, e);\n    }\n\n    await sleep(200);\n  }\n\n  // Descargar archivo oficial con iconos reales de Wowhead\n  const jsContent = `// ENCANTAMIENTOS Y CONSUMIBLES OFICIALES EXTRAÍDOS\\nwindow.WOWHEAD_SPEC_ENCHANTS_AND_CONSUMABLES = ${JSON.stringify(results, null, 2)};\\n`;\n  const blob = new Blob([jsContent], { type: \"application/javascript\" });\n  const link = document.createElement(\"a\");\n  link.href = URL.createObjectURL(blob);\n  link.download = \"wowhead_data.js\";\n  document.body.appendChild(link);\n  link.click();\n  document.body.removeChild(link);\n\n  console.log(\"%c✅ ¡Extracción completada! Se descargó wowhead_data.js con TODOS los iconos reales extraídos directamente de los tooltips.\", \"color: #10b981; font-size: 16px; font-weight: bold;\");\n  return results;\n})();\n";
window.WOW_NEWS_EXTRACTOR_SCRIPT_CODE = `/**
 * EXTRACTOR OFICIAL DE NOTICIAS Y BLUE TRACKER DESDE WOWHEAD (CONSOLA)
 * 
 * INSTRUCCIONES:
 * 1. Abre https://www.wowhead.com en tu navegador.
 * 2. Presiona F12 y ve a la pestaña 'Console'.
 * 3. Pega este código y presiona Enter.
 * 4. El script extraerá los titulares y resúmenes del Blue Tracker y Recent News de Wowhead.
 * 5. Se descargará el archivo 'wow_news_data.js' listo para subirlo al panel admin.
 */

(async function extractWowheadNews() {
  console.log('📰 Extrayendo noticias y Blue Tracker de Wowhead...');
  
  const blueTracker = [];
  const recentNews = [];

  // Extraer Blue Tracker
  document.querySelectorAll('.news-list-card, [data-news-type="blue"], .bluetracker li, a[href*="/news="]').forEach((el, idx) => {
    const title = el.innerText.trim();
    const href = el.getAttribute('href') || '';
    if (title.length > 10 && blueTracker.length < 10) {
      blueTracker.push({
        id: 'blue-' + (idx + 1),
        region: title.includes('EU') ? 'EU' : 'US',
        timeAgo: 'Reciente',
        date: new Date().toLocaleDateString(),
        title: title.slice(0, 100),
        author: 'Blizzard Entertainment',
        tag: 'Blue Post',
        category: 'Balance',
        badgeColor: 'border-sky-500/60 bg-sky-950/80 text-sky-300',
        summary: title,
        content: '<p class=\"text-sm text-slate-300 leading-relaxed\">' + title + '</p>'
      });
    }
  });

  const dataset = { blueTracker, recentNews };
  const fileContent = '// BASE DE DATOS DE NOTICIAS WOWHEAD EXTRAÍDAS\\nwindow.WOW_NEWS_DATABASE = ' + JSON.stringify(dataset, null, 2) + ';\\n';
  const blob = new Blob([fileContent], { type: 'text/javascript' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'wow_news_data.js';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  console.log('✅ wow_news_data.js descargado con éxito.');
  return dataset;
})();`;

window.ARCHON_HEALER_EXTRACTOR_SCRIPT_CODE = `/**
 * EXTRACTOR OFICIAL DE ABALORIOS HEALER PARA ARCHON.GG (CONSOLA DE NAVEGADOR)
 * 
 * INSTRUCCIONES:
 * 1. Abre https://www.archon.gg/wow en tu navegador (Chrome, Edge, Firefox).
 * 2. Presiona F12 y ve a la pestaña 'Console' (Consola).
 * 3. Pega todo este código y presiona Enter.
 * 4. Espera a que termine de escanear los 7 healers en Mítica+ y Banda.
 * 5. Se descargará automáticamente el archivo 'archon_healers.js' listo para subirlo en el Panel Admin.
 */

(async () => {
  console.log('%c🚀 INICIANDO EXTRACCIÓN DE TODOS LOS HEALERS DE ARCHON...', 'color: #38bdf8; font-weight: bold; font-size: 14px;');

  const HEALER_TARGETS = [
    { classKey: 'paladin', specKey: 'holy', urlPath: 'holy/paladin' },
    { classKey: 'priest', specKey: 'discipline', urlPath: 'discipline/priest' },
    { classKey: 'priest', specKey: 'holy_priest', urlPath: 'holy/priest' },
    { classKey: 'shaman', specKey: 'restoration_shaman', urlPath: 'restoration/shaman' },
    { classKey: 'druid', specKey: 'restoration_druid', urlPath: 'restoration/druid' },
    { classKey: 'monk', specKey: 'mistweaver', urlPath: 'mistweaver/monk' },
    { classKey: 'evoker', specKey: 'preservation', urlPath: 'preservation/evoker' }
  ];

  const MODES = [
    { key: 'mplus', urlSub: 'mythic-plus/trinkets/high-keys/all-dungeons/this-week' },
    { key: 'raid', urlSub: 'raid/trinkets/mythic/all-bosses' }
  ];

  const masterData = {};

  function parseHtmlTrinkets(htmlText) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlText, 'text/html');
    const rows = [];

    doc.querySelectorAll('table.react-table tbody tr').forEach(tr => {
      const link = tr.querySelector('a[href*="wowhead.com/item="]');
      if (!link) return;
      const itemMatch = link.href.match(/item=(\\d+)/);
      if (!itemMatch) return;
      const itemId = parseInt(itemMatch[1]);
      
      const nameEl = tr.querySelector('.icon__label, a[href*="wowhead.com/item="] span span');
      const name = nameEl ? nameEl.innerText.trim() : ('Item ' + itemId);
      
      const popEl = tr.querySelector('.react-table__cell--popularityAndReportLink span, .react-table__cell--popularity span');
      const popText = popEl ? popEl.innerText.trim() : '0%';
      const popMatch = popText.match(/([0-9.]+)%/);
      const popularity = popMatch ? parseFloat(popMatch[1]) : 0;
      
      const maxKeyEl = tr.querySelector('.react-table__cell--maxKey span');
      const maxKey = maxKeyEl ? maxKeyEl.innerText.trim() : '';
      
      const imgEl = tr.querySelector('img.icon__image');
      let icon = '';
      if (imgEl && imgEl.src) {
        const im = imgEl.src.match(/\\/abilities\\/([^.]+)/);
        if (im) icon = im[1];
      }
      
      rows.push({ itemId, name, popularity, maxKey, icon });
    });

    return rows;
  }

  for (const h of HEALER_TARGETS) {
    if (!masterData[h.classKey]) masterData[h.classKey] = {};
    if (!masterData[h.classKey][h.specKey]) masterData[h.classKey][h.specKey] = {};

    for (const m of MODES) {
      const url = \`https://www.archon.gg/wow/builds/\${h.urlPath}/\${m.urlSub}\`;
      console.log(\`Descargando (\${h.classKey} - \${h.specKey} - \${m.key})...\`);
      try {
        const resp = await fetch(url);
        if (resp.ok) {
          const html = await resp.text();
          const trinkets = parseHtmlTrinkets(html);
          masterData[h.classKey][h.specKey][m.key] = trinkets;
          console.log(\`  ✓ \${trinkets.length} abalorios encontrados.\`);
        } else {
          console.warn(\`  ✗ HTTP \${resp.status} en \${url}\`);
          masterData[h.classKey][h.specKey][m.key] = [];
        }
      } catch (e) {
        console.error(\`  ✗ Error en \${url}:\`, e);
        masterData[h.classKey][h.specKey][m.key] = [];
      }
      await new Promise(r => setTimeout(r, 400));
    }
  }

  const finalOutput = JSON.stringify(masterData, null, 2);
  const fileContent = '// Archon.gg Top Healer Trinkets\\nwindow.ARCHON_HEALER_TRINKETS = ' + finalOutput + ';\\n';

  const blob = new Blob([fileContent], { type: 'text/javascript' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'archon_healers.js';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  console.log('%c✅ ¡EXTRACCIÓN COMPLETA! Se descargó archon_healers.js y se copió al portapapeles.', 'color: #22c55e; font-weight: bold; font-size: 16px;');
  
  if (typeof copy === 'function') {
    copy(finalOutput);
  }
  
  return masterData;
})();
`;


window.STAT_PRIORITIES_EXTRACTOR_SCRIPT_CODE = "/**\r\n * EXTRACTOR OFICIAL PARA WOWHEAD (CONSOLA DE NAVEGADOR) - VERSIÓN PERFECCIONADA\r\n * \r\n * INSTRUCCIONES:\r\n * 1. Abre https://www.wowhead.com en tu navegador.\r\n * 2. Presiona F12 y ve a la pestaña 'Console' (Consola).\r\n * 3. Pega todo este código y presiona Enter.\r\n * 4. Espera a que termine el escaneo (20-30 seg).\r\n * 5. Se descargará automáticamente el archivo 'wow_stat_priorities.js'.\r\n */\r\n\r\n(async function extractWowheadStatPriorities() {\r\n  console.log('🚀 Iniciando extracción masiva de Stat Priorities y Hero Trees desde Wowhead...');\r\n\r\n  const HERO_TREES_MAP = {\r\n    'deathknight_blood': ['Deathbringer', \"San'layn\"],\r\n    'deathknight_frost_dk': ['Deathbringer', 'Rider of the Apocalypse'],\r\n    'deathknight_unholy': ['Rider of the Apocalypse', \"San'layn\"],\r\n    'demonhunter_havoc': ['Aldrachi Reaver', 'Fel-Scarred'],\r\n    'demonhunter_vengeance': ['Aldrachi Reaver', 'Fel-Scarred'],\r\n    'druid_balance': [\"Elune's Chosen\", 'Keeper of the Grove'],\r\n    'druid_feral': ['Druid of the Claw', 'Wildstalker'],\r\n    'druid_guardian': ['Druid of the Claw', \"Elune's Chosen\"],\r\n    'druid_restoration_druid': ['Keeper of the Grove', 'Wildstalker'],\r\n    'evoker_devastation': ['Flameshaper', 'Scalecommander'],\r\n    'evoker_preservation': ['Chronowarden', 'Flameshaper'],\r\n    'evoker_augmentation': ['Chronowarden', 'Scalecommander'],\r\n    'hunter_beastmastery': ['Dark Ranger', 'Pack Leader'],\r\n    'hunter_marksmanship': ['Dark Ranger', 'Sentinel'],\r\n    'hunter_survival': ['Pack Leader', 'Sentinel'],\r\n    'mage_arcane': ['Spellslinger', 'Sunfury'],\r\n    'mage_fire': ['Frostfire', 'Sunfury'],\r\n    'mage_frost_mage': ['Frostfire', 'Spellslinger'],\r\n    'monk_brewmaster': ['Master of Harmony', 'Shado-Pan'],\r\n    'monk_mistweaver': ['Conduit of the Celestials', 'Master of Harmony'],\r\n    'monk_windwalker': ['Conduit of the Celestials', 'Shado-Pan'],\r\n    'paladin_holy_paladin': ['Herald of the Sun', 'Lightsmith'],\r\n    'paladin_protection_paladin': ['Lightsmith', 'Templar'],\r\n    'paladin_retribution': ['Herald of the Sun', 'Templar'],\r\n    'priest_discipline': ['Oracle', 'Voidweaver'],\r\n    'priest_holy_priest': ['Archon', 'Oracle'],\r\n    'priest_shadow': ['Archon', 'Voidweaver'],\r\n    'rogue_assassination': ['Deathstalker', 'Fatebound'],\r\n    'rogue_outlaw': ['Fatebound', 'Trickster'],\r\n    'rogue_subtlety': ['Deathstalker', 'Trickster'],\r\n    'shaman_elemental': ['Farseer', 'Stormbringer'],\r\n    'shaman_enhancement': ['Stormbringer', 'Totemic'],\r\n    'shaman_restoration_shaman': ['Farseer', 'Totemic'],\r\n    'warlock_affliction': ['Hellcaller', 'Soul Harvester'],\r\n    'warlock_demonology': ['Diabolist', 'Soul Harvester'],\r\n    'warlock_destruction': ['Diabolist', 'Hellcaller'],\r\n    'warrior_arms': ['Colossus', 'Slayer'],\r\n    'warrior_fury': ['Mountain Thane', 'Slayer'],\r\n    'warrior_protection_warrior': ['Colossus', 'Mountain Thane']\r\n  };\r\n\r\n  const SPECS = [\r\n    { classKey: 'deathknight', classSlug: 'death-knight', specKey: 'blood', name: 'Blood Death Knight', guide: 'blood/stat-priority-pve-tank' },\r\n    { classKey: 'deathknight', classSlug: 'death-knight', specKey: 'frost_dk', name: 'Frost Death Knight', guide: 'frost/stat-priority-pve-dps' },\r\n    { classKey: 'deathknight', classSlug: 'death-knight', specKey: 'unholy', name: 'Unholy Death Knight', guide: 'unholy/stat-priority-pve-dps' },\r\n    { classKey: 'demonhunter', classSlug: 'demon-hunter', specKey: 'havoc', name: 'Havoc Demon Hunter', guide: 'havoc/stat-priority-pve-dps' },\r\n    { classKey: 'demonhunter', classSlug: 'demon-hunter', specKey: 'vengeance', name: 'Vengeance Demon Hunter', guide: 'vengeance/stat-priority-pve-tank' },\r\n    { classKey: 'druid', classSlug: 'druid', specKey: 'balance', name: 'Balance Druid', guide: 'balance/stat-priority-pve-dps' },\r\n    { classKey: 'druid', classSlug: 'druid', specKey: 'feral', name: 'Feral Druid', guide: 'feral/stat-priority-pve-dps' },\r\n    { classKey: 'druid', classSlug: 'druid', specKey: 'guardian', name: 'Guardian Druid', guide: 'guardian/stat-priority-pve-tank' },\r\n    { classKey: 'druid', classSlug: 'druid', specKey: 'restoration_druid', name: 'Restoration Druid', guide: 'restoration/stat-priority-pve-healer' },\r\n    { classKey: 'evoker', classSlug: 'evoker', specKey: 'devastation', name: 'Devastation Evoker', guide: 'devastation/stat-priority-pve-dps' },\r\n    { classKey: 'evoker', classSlug: 'evoker', specKey: 'preservation', name: 'Preservation Evoker', guide: 'preservation/stat-priority-pve-healer' },\r\n    { classKey: 'evoker', classSlug: 'evoker', specKey: 'augmentation', name: 'Augmentation Evoker', guide: 'augmentation/stat-priority-pve-dps' },\r\n    { classKey: 'hunter', classSlug: 'hunter', specKey: 'beastmastery', name: 'Beast Mastery Hunter', guide: 'beast-mastery/stat-priority-pve-dps' },\r\n    { classKey: 'hunter', classSlug: 'hunter', specKey: 'marksmanship', name: 'Marksmanship Hunter', guide: 'marksmanship/stat-priority-pve-dps' },\r\n    { classKey: 'hunter', classSlug: 'hunter', specKey: 'survival', name: 'Survival Hunter', guide: 'survival/stat-priority-pve-dps' },\r\n    { classKey: 'mage', classSlug: 'mage', specKey: 'arcane', name: 'Arcane Mage', guide: 'arcane/stat-priority-pve-dps' },\r\n    { classKey: 'mage', classSlug: 'mage', specKey: 'fire', name: 'Fire Mage', guide: 'fire/stat-priority-pve-dps' },\r\n    { classKey: 'mage', classSlug: 'mage', specKey: 'frost_mage', name: 'Frost Mage', guide: 'frost/stat-priority-pve-dps' },\r\n    { classKey: 'monk', classSlug: 'monk', specKey: 'brewmaster', name: 'Brewmaster Monk', guide: 'brewmaster/stat-priority-pve-tank' },\r\n    { classKey: 'monk', classSlug: 'monk', specKey: 'mistweaver', name: 'Mistweaver Monk', guide: 'mistweaver/stat-priority-pve-healer' },\r\n    { classKey: 'monk', classSlug: 'monk', specKey: 'windwalker', name: 'Windwalker Monk', guide: 'windwalker/stat-priority-pve-dps' },\r\n    { classKey: 'paladin', classSlug: 'paladin', specKey: 'holy_paladin', name: 'Holy Paladin', guide: 'holy/stat-priority-pve-healer' },\r\n    { classKey: 'paladin', classSlug: 'paladin', specKey: 'protection_paladin', name: 'Protection Paladin', guide: 'protection/stat-priority-pve-tank' },\r\n    { classKey: 'paladin', classSlug: 'paladin', specKey: 'retribution', name: 'Retribution Paladin', guide: 'retribution/stat-priority-pve-dps' },\r\n    { classKey: 'priest', classSlug: 'priest', specKey: 'discipline', name: 'Discipline Priest', guide: 'discipline/stat-priority-pve-healer' },\r\n    { classKey: 'priest', classSlug: 'priest', specKey: 'holy_priest', name: 'Holy Priest', guide: 'holy/stat-priority-pve-healer' },\r\n    { classKey: 'priest', classSlug: 'priest', specKey: 'shadow', name: 'Shadow Priest', guide: 'shadow/stat-priority-pve-dps' },\r\n    { classKey: 'rogue', classSlug: 'rogue', specKey: 'assassination', name: 'Assassination Rogue', guide: 'assassination/stat-priority-pve-dps' },\r\n    { classKey: 'rogue', classSlug: 'rogue', specKey: 'outlaw', name: 'Outlaw Rogue', guide: 'outlaw/stat-priority-pve-dps' },\r\n    { classKey: 'rogue', classSlug: 'rogue', specKey: 'subtlety', name: 'Subtlety Rogue', guide: 'subtlety/stat-priority-pve-dps' },\r\n    { classKey: 'shaman', classSlug: 'shaman', specKey: 'elemental', name: 'Elemental Shaman', guide: 'elemental/stat-priority-pve-dps' },\r\n    { classKey: 'shaman', classSlug: 'shaman', specKey: 'enhancement', name: 'Enhancement Shaman', guide: 'enhancement/stat-priority-pve-dps' },\r\n    { classKey: 'shaman', classSlug: 'shaman', specKey: 'restoration_shaman', name: 'Restoration Shaman', guide: 'restoration/stat-priority-pve-healer' },\r\n    { classKey: 'warlock', classSlug: 'warlock', specKey: 'affliction', name: 'Affliction Warlock', guide: 'affliction/stat-priority-pve-dps' },\r\n    { classKey: 'warlock', classSlug: 'warlock', specKey: 'demonology', name: 'Demonology Warlock', guide: 'demonology/stat-priority-pve-dps' },\r\n    { classKey: 'warlock', classSlug: 'warlock', specKey: 'destruction', name: 'Destruction Warlock', guide: 'destruction/stat-priority-pve-dps' },\r\n    { classKey: 'warrior', classSlug: 'warrior', specKey: 'arms', name: 'Arms Warrior', guide: 'arms/stat-priority-pve-dps' },\r\n    { classKey: 'warrior', classSlug: 'warrior', specKey: 'fury', name: 'Fury Warrior', guide: 'fury/stat-priority-pve-dps' },\r\n    { classKey: 'warrior', classSlug: 'warrior', specKey: 'protection_warrior', name: 'Protection Warrior', guide: 'protection/stat-priority-pve-tank' }\r\n  ];\r\n\r\n  const baseWeights = [1.6, 1.3, 1.0, 0.7];\r\n\r\n  function parseTiersToWeights(tiers) {\r\n    const weights = { m: 1.0, c: 1.0, h: 1.0, v: 1.0 };\r\n    tiers.forEach((tierStats, tierIdx) => {\r\n      const w = baseWeights[tierIdx] !== undefined ? baseWeights[tierIdx] : 0.6;\r\n      tierStats.forEach(stKey => {\r\n        weights[stKey] = w;\r\n      });\r\n    });\r\n    return weights;\r\n  }\r\n\r\n  function parseStatList(items) {\r\n    const secondaryTiers = [];\r\n    items.forEach(it => {\r\n      const lower = it.toLowerCase();\r\n      if (lower.includes('agility') || lower.includes('strength') || lower.includes('intellect') || lower.includes('stamina')) {\r\n        return;\r\n      }\r\n      const found = [];\r\n      if (lower.includes('mastery')) found.push('m');\r\n      if (lower.includes('crit')) found.push('c');\r\n      if (lower.includes('haste')) found.push('h');\r\n      if (lower.includes('vers')) found.push('v');\r\n\r\n      if (found.length > 0) {\r\n        secondaryTiers.push(found);\r\n      }\r\n    });\r\n\r\n    if (secondaryTiers.length === 0) return null;\r\n\r\n    return {\r\n      rawList: items,\r\n      secondaryOrder: secondaryTiers.map(t => t.map(k => k === 'm' ? 'Mastery' : k === 'c' ? 'Crit' : k === 'h' ? 'Haste' : 'Vers').join(' = ')).join(' > '),\r\n      weights: parseTiersToWeights(secondaryTiers)\r\n    };\r\n  }\r\n\r\n  const results = {};\r\n\r\n  for (const item of SPECS) {\r\n    if (!results[item.classKey]) results[item.classKey] = {};\r\n    \r\n    console.log('🔍 [' + item.name + '] Obteniendo guía de stats...');\r\n    const guideUrl = 'https://www.wowhead.com/guide/classes/' + item.classSlug + '/' + item.guide;\r\n    const expectedTrees = HERO_TREES_MAP[item.classKey + '_' + item.specKey] || [];\r\n    \r\n    try {\r\n      const res = await fetch(guideUrl);\r\n      if (!res.ok) {\r\n        console.warn('⚠️ No se pudo cargar URL: ' + guideUrl + ' (Status: ' + res.status + ')');\r\n        continue;\r\n      }\r\n      const html = await res.text();\r\n      const parser = new DOMParser();\r\n      const doc = parser.parseFromString(html, 'text/html');\r\n\r\n      const heroTrees = {};\r\n      const allOls = Array.from(doc.querySelectorAll('ol'));\r\n      const parsedLists = [];\r\n\r\n      allOls.forEach(ol => {\r\n        const items = Array.from(ol.querySelectorAll('li')).map(li => li.textContent.trim());\r\n        const parsed = parseStatList(items);\r\n        if (parsed) {\r\n          // Obtener texto del contenedor o encabezado previo\r\n          let headerText = '';\r\n          let container = ol.parentElement;\r\n          for (let i = 0; i < 4 && container; i++) {\r\n            const txt = container.textContent || '';\r\n            expectedTrees.forEach(tree => {\r\n              if (new RegExp('\\\\b' + tree + '\\\\b', 'i').test(txt)) {\r\n                headerText = tree;\r\n              }\r\n            });\r\n            if (headerText) break;\r\n            container = container.parentElement;\r\n          }\r\n\r\n          if (!headerText) {\r\n            let prev = ol.previousElementSibling;\r\n            while (prev) {\r\n              const prevTxt = prev.textContent || '';\r\n              expectedTrees.forEach(tree => {\r\n                if (new RegExp('\\\\b' + tree + '\\\\b', 'i').test(prevTxt)) {\r\n                  headerText = tree;\r\n                }\r\n              });\r\n              if (headerText) break;\r\n              prev = prev.previousElementSibling;\r\n            }\r\n          }\r\n\r\n          parsedLists.push({\r\n            header: headerText,\r\n            data: parsed\r\n          });\r\n        }\r\n      });\r\n\r\n      // Asociar listas a los Hero Trees esperados\r\n      parsedLists.forEach(pl => {\r\n        if (pl.header && expectedTrees.includes(pl.header)) {\r\n          heroTrees[pl.header] = pl.data;\r\n        }\r\n      });\r\n\r\n      // Si falta alguno de los 2 Hero Trees, usar la primera lista encontrada o repartir\r\n      if (parsedLists.length > 0) {\r\n        expectedTrees.forEach((tree, idx) => {\r\n          if (!heroTrees[tree]) {\r\n            const fallbackData = parsedLists[idx] ? parsedLists[idx].data : parsedLists[0].data;\r\n            heroTrees[tree] = fallbackData;\r\n          }\r\n        });\r\n      }\r\n\r\n      // Si aún no hay nada (guía sin <ol>), crear default\r\n      if (Object.keys(heroTrees).length === 0) {\r\n        const defaultData = {\r\n          rawList: ['Mastery', 'Haste', 'Critical Strike', 'Versatility'],\r\n          secondaryOrder: 'Mastery > Haste > Crit > Vers',\r\n          weights: { m: 1.6, h: 1.3, c: 1.0, v: 0.7 }\r\n        };\r\n        expectedTrees.forEach(tree => {\r\n          heroTrees[tree] = defaultData;\r\n        });\r\n      }\r\n\r\n      results[item.classKey][item.specKey] = {\r\n        name: item.name,\r\n        guideUrl: guideUrl,\r\n        heroTrees: heroTrees\r\n      };\r\n\r\n      console.log('✅ [' + item.name + '] Hero Trees asignados:', Object.keys(heroTrees).join(' | '));\r\n    } catch (e) {\r\n      console.warn('❌ Error procesando ' + item.name + ':', e);\r\n    }\r\n  }\r\n\r\n  const fileContent = '// WOWHEAD STAT PRIORITIES Y HERO TREES OFICIALES EXTRAÍDOS\\nwindow.WOWHEAD_STAT_PRIORITIES = ' + JSON.stringify(results, null, 2) + ';\\n';\r\n\r\n  const blob = new Blob([fileContent], { type: 'text/javascript' });\r\n  const downloadUrl = URL.createObjectURL(blob);\r\n  const a = document.createElement('a');\r\n  a.href = downloadUrl;\r\n  a.download = 'wow_stat_priorities.js';\r\n  document.body.appendChild(a);\r\n  a.click();\r\n  document.body.removeChild(a);\r\n  URL.revokeObjectURL(downloadUrl);\r\n\r\n  console.log('🎉 ¡Extracción de las 39 Specs completada y archivo wow_stat_priorities.js descargado con éxito!');\r\n  return results;\r\n})();\r\n";
